"use client";

import { useEffect, useMemo, useState } from "react";

/**
 * Coaching engine entry point.
 *
 * DEMO MODE: responses are pre-generated by Claude from the persona data and
 * replayed with a streaming effect, so the demo needs no API key.
 *
 * LIVE MODE (production): the same UI calls a server route that builds the
 * context (profile + computed stats + recent workouts + check-ins + memory)
 * and streams Claude's reply, e.g.
 *
 *   const stream = anthropic.messages.stream({
 *     model: "claude-sonnet-5-5",
 *     system: COACH_SYSTEM_PROMPT + knowledgeBase,
 *     messages: [...history, { role: "user", content: buildContext(user) + question }],
 *   });
 *
 * The API key stays on the server; the browser only receives streamed text.
 */

/** Replays text word-by-word to mimic a streamed model response. */
export function useStreamedText(text: string | null, wordsPerTick = 3, tickMs = 35) {
  const [count, setCount] = useState(0);
  const tokens = useMemo(() => (text ? text.split(/(\s+)/) : []), [text]);

  useEffect(() => {
    if (!tokens.length) return;
    const id = setInterval(() => {
      setCount((c) => {
        const next = c + wordsPerTick * 2;
        if (next >= tokens.length) clearInterval(id);
        return next;
      });
    }, tickMs);
    return () => clearInterval(id);
  }, [tokens, wordsPerTick, tickMs]);

  return { shown: tokens.slice(0, count).join(""), done: tokens.length > 0 && count >= tokens.length };
}
